import csv, json, os, sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read(d, name):
    p = os.path.join(d, name)
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.reader(f))
    rows = [r for r in rows if any(c.strip() for c in r)]
    if not rows:
        return []
    hdr = [h.strip() for h in rows[0]]
    out = []
    for r in rows[1:]:
        r = [c.strip() for c in r]
        r += [""] * (len(hdr) - len(r))
        out.append(dict(zip(hdr, r)))
    return out


def ftime(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def fmt(ts, tz):
    dt = datetime.fromtimestamp(ts, tz)
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, secs // 3600, secs % 3600 // 60)


def main(inp, outp):
    req = json.load(open(os.path.join(inp, "request.json"), encoding="utf-8-sig"))
    dates = sorted(set(req["service_dates"]))
    agencies = read(inp, "agency.txt")
    agtz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    default_tz = agencies[0]["agency_timezone"]
    stops = {s["stop_id"]: s for s in read(inp, "stops.txt")}
    routes = {r["route_id"]: r for r in read(inp, "routes.txt")}
    trips = {t["trip_id"]: t for t in read(inp, "trips.txt")}
    cal = {c["service_id"]: c for c in read(inp, "calendar.txt")}
    cdates = {}
    for c in read(inp, "calendar_dates.txt"):
        cdates[(c["service_id"], c["date"])] = c["exception_type"]
    freqs = {}
    for f in read(inp, "frequencies.txt"):
        freqs.setdefault(f["trip_id"], []).append(f)
    st = {}
    for r in read(inp, "stop_times.txt"):
        r["_seq"] = int(r["stop_sequence"])
        st.setdefault(r["trip_id"], []).append(r)
    for v in st.values():
        v.sort(key=lambda r: r["_seq"])

    def board_stop(sid):
        s = stops[sid]
        p = s.get("parent_station", "")
        return p if p else sid

    def runs(service, d):
        ex = cdates.get((service, d.strftime("%Y%m%d")))
        if ex == "1":
            return True
        if ex == "2":
            return False
        c = cal.get(service)
        if not c:
            return False
        ds = d.strftime("%Y%m%d")
        if not (c["start_date"] <= ds <= c["end_date"]):
            return False
        return c[["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][d.weekday()]] == "1"

    def tz_of(bid):
        return ZoneInfo(stops[bid].get("stop_timezone") or default_tz)

    # trip pre-computation
    tinfo = {}
    for tid, rows in st.items():
        t = trips[tid]
        times = []
        for r in rows:
            x = r.get("departure_time") or r.get("arrival_time")
            times.append(ftime(x) if x else None)
        known = [i for i, x in enumerate(times) if x is not None]
        for a, b in zip(known, known[1:]):
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // (b - a)
        last = stops[rows[-1]["stop_id"]]
        lastname = stops[board_stop(rows[-1]["stop_id"])]["stop_name"]
        deps = []
        for i, r in enumerate(rows[:-1]):
            if r.get("pickup_type") == "1":
                continue
            sid = r["stop_id"]
            head = r.get("stop_headsign") or t.get("trip_headsign") or lastname
            deps.append((times[i] - times[0], times[i], sid, head))
        tinfo[tid] = deps

    boards = {}
    for bid, s in stops.items():
        if s.get("location_type", "") in ("", "0") and not s.get("parent_station"):
            boards[bid] = s
        elif s.get("location_type") == "1":
            boards[bid] = s

    result = []
    for ds in dates:
        d = date.fromisoformat(ds)
        per = {bid: [] for bid in boards}
        for tid, t in trips.items():
            if tid not in tinfo or not runs(t["service_id"], d):
                continue
            route = routes[t["route_id"]]
            ag = route["agency_id"]
            label = route.get("route_short_name") or route.get("route_long_name", "")
            atz = ZoneInfo(agtz[ag])
            noon = datetime(d.year, d.month, d.day, 12, tzinfo=atz)
            origin = int(noon.timestamp()) - 43200
            fl = freqs.get(tid)
            for off, tm, sid, head in tinfo[tid]:
                bid = board_stop(sid)
                tz = tz_of(bid)
                plat = stops[sid].get("platform_code") or None

                def mk(kind, a, until, hw):
                    ts = origin + a
                    return (ts, label, head, tid, plat or "", plat is not None, {
                        "kind": kind, "time": fmt(ts, tz),
                        "until": fmt(origin + until, tz) if until is not None else None,
                        "headway_secs": hw, "route": label, "headsign": head,
                        "trip": tid, "platform": plat, "agency": ag})
                if not fl:
                    per[bid].append(mk("scheduled", tm, None, None))
                    continue
                for w in fl:
                    s0, e0, hw = ftime(w["start_time"]), ftime(w["end_time"]), int(w["headway_secs"])
                    if s0 >= e0:
                        continue
                    starts = list(range(s0, e0, hw))
                    if w.get("exact_times") == "1":
                        for s_ in starts:
                            per[bid].append(mk("scheduled", s_ + off, None, None))
                    else:
                        per[bid].append(mk("interval", starts[0] + off, starts[-1] + off, hw))
        for bid, s in boards.items():
            lst = sorted(per[bid], key=lambda x: x[:6])
            result.append({"stop_id": bid, "name": s["stop_name"], "timezone": str(tz_of(bid)),
                           "service_date": ds, "departures": [x[6] for x in lst]})
    result.sort(key=lambda b: (b["stop_id"], b["service_date"]))
    with open(outp, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": result}, f, ensure_ascii=False)


